String _secretValueSegmentRow({
  required String segment,
  required int index,
  required TuiPromptState state,
  required int inner,
  required bool focused,
}) {
  final isFirst = index == 0;
  final marker = focused && isFirst ? '${_accent('>')} ' : '  ';
