    /// STABLE markers only: quiescence after the full string, then the
    /// masking property (gh-1244). Never waits on an exact transient
    /// bullet count — the PTY can paint past it before the wait evaluates,
    /// and on the raw wire the focused row's cursor cell is wrapped in
    /// inverse-video escapes, so five consecutive `•` need never exist in
    /// the stream at all.
    Future<void> typeSecret(String secret) async {
      harness.sendText(secret);
      await harness.waitForOutput(settleMs: 300);
      // (a) The frame-closed value row carries exactly one bullet per
      // typed char — i.e. masking held from the first keystroke through
      // the last. The tool row (`• request_secret · …`) is not
      // frame-closed, so the `│` guard pins this to the sheet row.
      final valueRow = harness.screenLines.firstWhere(
        (l) => l.contains('•') && l.trimRight().endsWith('│'),
        reason: 'the value row must render the masked secret',
      );
