  final marker = focused ? '${_accent('>')} ' : '  ';
  return [
    _wrapBodyLine(_dim('Name (UPPER_SNAKE):'), inner, dim: true),
    _wrapBodyLine('$marker$nameRow', inner, bold: committedName.isNotEmpty),
  ];
}

